(()=>{'use strict';const trigger=document.querySelector('#deskSearch'),header=document.querySelector('main>header');if(!trigger||!header)return;const box=document.createElement('div');box.id='headerSearchBox';box.className='header-search-box';box.hidden=true;box.innerHTML='<span aria-hidden="true">⌕</span><input type="search" id="headerTaskSearch" placeholder="جست‌وجوی کارها…" aria-label="جست‌وجوی کارها" autocomplete="off"><button type="button" aria-label="بستن جست‌وجو">×</button>';header.append(box);const input=box.querySelector('input'),closeButton=box.querySelector('button');let timer;function target(){return document.querySelector('#personalSearch,#sharedSearch,#claritySearch')}function prepare(){if(target())return true;const personal=!!window.SAMANDIS_PERSONAL_MODE,nav=document.querySelector('[data-desk-view="'+(personal?'mine':'all')+'"]');nav?.click();return !!target()}function open(){if(!prepare())return;input.value=target()?.value||'';box.hidden=false;header.classList.add('header-search-open');trigger.setAttribute('aria-expanded','true');input.focus()}function close(){clearTimeout(timer);if(timer){timer=null;apply()}box.hidden=true;header.classList.remove('header-search-open');trigger.setAttribute('aria-expanded','false');trigger.focus()}function apply(){const original=target();if(!original)return;const focused=document.activeElement===input,pos=input.selectionStart;original.value=input.value;original.dispatchEvent(new Event('input',{bubbles:true}));if(focused){input.focus();if(pos!==null&&input.type==='text')input.setSelectionRange(pos,pos)}}trigger.setAttribute('aria-haspopup','true');trigger.setAttribute('aria-controls',box.id);trigger.setAttribute('aria-expanded','false');trigger.onclick=()=>box.hidden?open():close();closeButton.onclick=close;input.oninput=()=>{clearTimeout(timer);timer=setTimeout(()=>{timer=null;apply()},160)};input.onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();close()}if(e.key==='Enter'){e.preventDefault();clearTimeout(timer);timer=null;apply()}};document.addEventListener('keydown',e=>{if(e.key==='/'&&!e.ctrlKey&&!e.metaKey&&!e.altKey&&!document.querySelector('dialog[open]')&&!/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)&&!e.target.isContentEditable){e.preventDefault();e.stopImmediatePropagation();open()}},true);document.addEventListener('pointerdown',e=>{if(!box.hidden&&!box.contains(e.target)&&!trigger.contains(e.target)){box.hidden=true;header.classList.remove('header-search-open');trigger.setAttribute('aria-expanded','false')}});})();
